Recall that if $\mathcal C$ is a category and $X_\bullet$ is a simplicial set, a \emph{diagram} $X_\bullet\to\mathcal C$ is a map of simplicial sets $X_\bullet\to N_\bullet\mathcal C$ where $N_\bullet\mathcal C$ denotes the \emph{nerve}\footnote{An $n$-simplex $\Delta^n\to N_\bullet\mathcal C$ is a diagram $A_0\xrightarrow{f_{01}}A_1\xrightarrow{f_{12}}\cdots\xrightarrow{f_{n-1,n}}A_n$ in $\mathcal C$.  Strictly speaking, $N_\bullet\mathcal C$ is not a simplicial \emph{set} unless $\mathcal C$ is small.} of $\mathcal C$.  Concretely, a diagram $F:X_\bullet\to\mathcal C$ is the data of:
\begin{rlist}
\item For every vertex $v\in X_0$, an object $A_v\in\mathcal C$.
\item For every edge $e\in X_1$ from $v_0$ to $v_1$, a morphism $f_e:A_{v_0}\to A_{v_1}$ in $\mathcal C$.
\setcounter{rcountsave}{\value{rcounti}}
\end{rlist}
such that:
\begin{rlist}
\setcounter{rcounti}{\value{rcountsave}}
\item For every degenerate edge $e\in X_1$ over vertex a $v$, we have $f_e=\operatorname{id}_{A_v}$.
\item For every face in $X_2$ spanning edges $e_{01},e_{12},e_{02}$, we have $f_{e_{12}}\circ f_{e_{01}}=f_{e_{02}}$.
\end{rlist}
We often speak of a diagram $X_\bullet\to\mathcal C$ where $X_\bullet$ is only a \emph{semi}simplicial set, in which case we ignore condition (\ref{degenerateisIDdiagram}).

Since $\tilde Z_\bullet\to Z_\bullet$ is a trivial Kan fibration (Proposition \ref{trivialKanfibration}), there exists a $2$-simplex in $\tilde Z_\bullet$ all of whose edges are $\sigma$.  Associated to this $2$-simplex is a chain homotopy $h:R[[\mathcal P]]\to R[[\mathcal P]]$ between $(1-\epsilon)$ and $(1-\epsilon)\circ(1-\epsilon)$; in other words:
\begin{equation}
\epsilon=dh+hd+\epsilon^2
\end{equation}

From the claim, we make the following two observations:
\begin{rlist}
\item We have $\left|d(p)\right|_a,\left|\epsilon(p)\right|_a,\left|h(p)\right|_a\leq\left|p\right|_a$.
\item For all $M<\infty$ and $p\in\mathcal P$, there exists $N<\infty$ such that any length $N$ composition of $d,\epsilon,h$ applied to $p$ has $a$-adic norm $\leq e^{-M}$.
\end{rlist}
(the second observation also uses Definition \ref{semisimplicialfcdef}(\ref{novikovfiniteness})).

Now iterating the identity $\epsilon=dh+hd+\epsilon^2$, we are led to the following infinite series:\footnote{The coefficients $\frac 1n\binom{2n-2}{n-1}$ are integers (Catalan numbers $C_{n-1}$), so writing this expression does not make any implicit assumptions on the ring $R$.}
\begin{equation}
\epsilon=\sum_{n=1}^\infty\frac 1n\binom{2n-2}{n-1}(hd+dh)^n
\end{equation}
which by observations (\ref{firstO})--(\ref{secondO}) converges in the $a$-adic topology when applied to any element of $R[[\mathcal P]]$.

\textbf{Defining $\mathbb H$ over $0$-simplices.}\  Fix some $0$-simplex $v$ of $Z_\bullet$.  For every lift $\tilde v$, we have an object $\widetilde{\mathbb H}(\tilde v)$.  Furthermore, for every lift $\tilde e$ of the degenerate $1$-simplex $e$ over $v$, we get a map $\widetilde{\mathbb H}(\tilde v_1)\xrightarrow{\widetilde{\mathbb H}(\tilde e)}\widetilde{\mathbb H}(\tilde v_2)$, which is the identity map if $\tilde v_1=\tilde v_2$.  Finally, for every lift $\tilde f$ of the degenerate $2$-simplex $f$ over $v$, the following diagram commutes:
\begin{equation} \begin{tikzcd}[row sep = small]
&\widetilde{\mathbb H}(\tilde v_2)\ar{rd}{\widetilde{\mathbb H}(\tilde e_{23})}&{}\cr
\widetilde{\mathbb H}(\tilde v_1)\ar{ur}{\widetilde{\mathbb H}(\tilde e_{12})}\ar{rr}[swap]{\widetilde{\mathbb H}(\tilde e_{13})}&&{\widetilde{\mathbb H}(\tilde v_3)}
\end{tikzcd}
\end{equation}
where $\tilde e_{12},\tilde e_{23},\tilde e_{13}$ are the edges of $\tilde f$.  Using that $\tilde Z_\bullet\to Z_\bullet$ is a trivial Kan fibration to conclude that we can always find lifts with specified boundary conditions, it follows that all $\widetilde{\mathbb H}(\tilde v)$ are canonically isomorphic.  Thus there exists a unique choice for $\mathbb H(v)$.

\textbf{Defining $\mathbb H$ over $n$-simplices for $n\geq 2$.}\  We just need to check that the following diagram commutes for all $2$-simplices $f$ in $Z_\bullet$:
\begin{equation}
\begin{tikzcd}[row sep = small]
&\mathbb H(v_2)\ar{rd}{\mathbb H(e_{23})}&{}\cr
\mathbb H(v_1)\ar{ur}{\mathbb H(e_{12})}\ar{rr}[swap]{\mathbb H(e_{13})}&&{\mathbb H(v_3)}
\end{tikzcd}
\end{equation}
where $e_{12},e_{23},e_{13}$ are the edges of $f$.  This follows from lifting $f$ and the commutativity of \eqref{liftedF}.

There are canonical ``comparison maps'':
\begin{align} C^\bullet_{S^1,\mathrm{vir}}(X;A)&\to C^\bullet_{\mathrm{vir}}(X;A)\\ C^\bullet_{S^1,\mathrm{vir}}(X\operatorname{rel}\partial;A)&\to C^\bullet_{\mathrm{vir}}(X\operatorname{rel}\partial;A)
\end{align}
and a canonical commutative diagram:
\begin{equation} \begin{CD}
C^{d+\bullet}_{S^1,\mathrm{vir}}(X\operatorname{rel}\partial;A)@>s_\ast>>C_{\dim E_A-\bullet-1}^{S^1}(E_A,E_A\setminus 0;\mathfrak o_{E_A}^\vee)^{\Gamma_A}\cr
@VVV@VV\pi^!V\cr
C^{d+\bullet}_{\mathrm{vir}}(X\operatorname{rel}\partial;A)@>s_\ast>>C_{\dim E_A-\bullet}(E_A,E_A\setminus 0;\mathfrak o_{E_A}^\vee)^{\Gamma_A}
\end{CD}
\end{equation}
($S^1$ acting trivially on $E_A$).

Furthermore, if $X$ is an almost free $S^1$-space and $A$ is \emph{locally $S^1$-orientable}, then there are canonical isomorphisms:
\begin{align} H^\bullet_{S^1,\mathrm{vir}}(X;A)&=\check H^\bullet(X/S^1;\pi_\ast\mathfrak o_X)\\ H^\bullet_{S^1,\mathrm{vir}}(X\operatorname{rel}\partial;A)&=\check H^\bullet(X/S^1;\pi_\ast\mathfrak o_{X\operatorname{rel}\partial})
\end{align}

By Poincar\'e duality, we have canonical isomorphisms:
\begin{equation} H_\bullet(M,M\setminus S^1p)=\begin{cases}H^0(S^1p;\mathfrak o_M)&\bullet=d\cr H^1(S^1p;\mathfrak o_M)&\bullet=d-1\cr 0&\text{otherwise}\end{cases}
